using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ──────────────────────────────────────────────
    // CalculateTotal – DataRow (compile-time constants)
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 2, 0.0, 20.00, DisplayName = "Two items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00, DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62, DisplayName = "Multiple items, 8% tax")]
    [DataRow(0.00, 5, 0.20, 0.00, DisplayName = "Zero price yields zero total")]
    [DataRow(99.99, 0, 0.15, 0.00, DisplayName = "Zero quantity yields zero total")]
    public void CalculateTotal_ValidInputs_ReturnsExpectedTotal(
        double unitPrice, int quantity, double taxRate, double expectedTotal)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expectedTotal, result);
    }

    // ──────────────────────────────────────────────
    // CalculateTotal – DynamicData (supports decimal precision & edge cases)
    // ──────────────────────────────────────────────

    public static IEnumerable<object[]> CalculateTotalEdgeCases
    {
        get
        {
            yield return new object[] { 0.01m, 1, 0.0m, 0.01m, "Minimum meaningful price" };
            yield return new object[] { 9999.99m, 100, 1.0m, 1_999_998.00m, "Large order, max tax" };
            yield return new object[] { 5.00m, 1, 0.0m, 5.00m, "No tax, simple case" };
            yield return new object[] { 19.99m, 4, 0.0625m, 84.9576m, "Fractional tax rate" };
        }
    }

    [TestMethod]
    [DynamicData(nameof(CalculateTotalEdgeCases))]
    public void CalculateTotal_EdgeCases_ReturnsExpectedTotal(
        decimal unitPrice, int quantity, decimal taxRate, decimal expectedTotal, string scenario)
    {
        var result = _calculator.CalculateTotal(unitPrice, quantity, taxRate);

        Assert.AreEqual(expectedTotal, result, $"Failed for scenario: {scenario}");
    }

    // ──────────────────────────────────────────────
    // CalculateTotal – invalid inputs throw
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(-1.0, 1, 0.1, DisplayName = "Negative unit price throws")]
    [DataRow(10.0, -1, 0.1, DisplayName = "Negative quantity throws")]
    [DataRow(10.0, 1, -0.1, DisplayName = "Negative tax rate throws")]
    [DataRow(10.0, 1, 1.5, DisplayName = "Tax rate above 1 throws")]
    public void CalculateTotal_InvalidInputs_ThrowsArgumentOutOfRangeException(
        double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    // ──────────────────────────────────────────────
    // ApplyDiscount – DataRow
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(100.00, 0.0, 100.00, DisplayName = "0% discount, full price")]
    [DataRow(100.00, 10.0, 90.00, DisplayName = "10% discount")]
    [DataRow(100.00, 50.0, 50.00, DisplayName = "50% discount")]
    [DataRow(100.00, 100.0, 0.00, DisplayName = "100% discount, free")]
    [DataRow(49.99, 25.0, 37.4925, DisplayName = "Fractional result")]
    public void ApplyDiscount_ValidInputs_ReturnsExpectedPrice(
        double price, double discountPercent, double expectedPrice)
    {
        var result = _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent);

        Assert.AreEqual((decimal)expectedPrice, result);
    }

    // ──────────────────────────────────────────────
    // ApplyDiscount – DynamicData from method
    // ──────────────────────────────────────────────

    public static IEnumerable<object[]> GetDiscountBoundaryData()
    {
        yield return new object[] { 200.00m, 0m, 200.00m };
        yield return new object[] { 200.00m, 100m, 0.00m };
        yield return new object[] { 0.00m, 50m, 0.00m };
        yield return new object[] { 1000.00m, 33.33m, 666.70m };
    }

    [TestMethod]
    [DynamicData(nameof(GetDiscountBoundaryData), DynamicDataSourceType.Method)]
    public void ApplyDiscount_BoundaryCases_ReturnsExpectedPrice(
        decimal price, decimal discountPercent, decimal expectedPrice)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expectedPrice, result);
    }

    // ──────────────────────────────────────────────
    // ApplyDiscount – invalid inputs throw
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(100.0, -1.0, DisplayName = "Negative discount throws")]
    [DataRow(100.0, 101.0, DisplayName = "Discount over 100% throws")]
    public void ApplyDiscount_InvalidDiscount_ThrowsArgumentOutOfRangeException(
        double price, double discountPercent)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent));
    }
}

